import angr
import claripy

# Load the binary
proj = angr.Project("{TARGET}", auto_load_libs=False)
base = 0x400000

# Key addresses
main_addr = base + 0x11c0
success_addr = base + 0x13eb  # prints "Correct!"
fail_addr = base + 0x1458     # prints "Wrong!"

# We need to skip the anti-debug check
# Anti-debug is at 0x1610, called at 0x1249

# Let's use SimProcedures for external functions
class FgetsHook(angr.SimProcedure):
    def run(self, buf, size, stream):
        # Store symbolic flag
        for i in range(64):
            c = self.state.solver.BVS(f'flag_{i}', 8)
            self.state.memory.store(buf + i, c)
            if i < 32:  # Constrain first 32 chars to printable
                self.state.solver.add(c >= 0x20)
                self.state.solver.add(c <= 0x7e)
        return buf

class AntiDebugHook(angr.SimProcedure):
    def run(self):
        return 0

class StrlenHook(angr.SimProcedure):
    def run(self, s):
        # Return concrete length for performance
        return claripy.BVV(26, 64)  # Try a length > 25

class StrcspnHook(angr.SimProcedure):
    def run(self, s1, s2):
        return claripy.BVV(26, 64)  # Return same as strlen

# Set up hooks
proj.hook_symbol('fgets', FgetsHook())
proj.hook_symbol('strlen', StrlenHook())
proj.hook_symbol('strcspn', StrcspnHook())
proj.hook(base + 0x1610, AntiDebugHook())

# Also need to hook other functions
class PrintfHook(angr.SimProcedure):
    def run(self, fmt, *args):
        return 0

class PutsHook(angr.SimProcedure):
    def run(self, s):
        return 0

class FopenHook(angr.SimProcedure):
    def run(self, path, mode):
        return 0

class FcloseHook(angr.SimProcedure):
    def run(self, f):
        return 0

class MemsetHook(angr.SimProcedure):
    def run(self, dest, c, n):
        return dest

class MemcpyChkHook(angr.SimProcedure):
    def run(self, dest, src, n, destlen):
        for i in range(n.concrete_value if n.concrete else 64):
            b = self.state.memory.load(src + i, 1)
            self.state.memory.store(dest + i, b)
        return dest

class MemcpyHook(angr.SimProcedure):
    def run(self, dest, src, n):
        return dest

class QsortHook(angr.SimProcedure):
    def run(self, base, nel, width, compar):
        return

proj.hook_symbol('__printf_chk', PrintfHook())
proj.hook_symbol('puts', PutsHook())
proj.hook_symbol('fopen', FopenHook())
proj.hook_symbol('fclose', FcloseHook())
proj.hook_symbol('memset', MemsetHook())
proj.hook_symbol('__memcpy_chk', MemcpyChkHook())
proj.hook_symbol('memcpy', MemcpyHook())
proj.hook_symbol('qsort', QsortHook())

print("All hooks set up")

# Create initial state
state = proj.factory.entry_state()

# Create simulation manager
simgr = proj.factory.simulation_manager(state)

# Explore to find path to success
print("Starting exploration...")
try:
    simgr.explore(find=success_addr, avoid=fail_addr, timeout=120)
    print(f"Found: {len(simgr.found)} states")
    if simgr.found:
        found_state = simgr.found[0]
        # Try to get the flag
        flag_addr = None
        # The flag was stored in the buffer passed to fgets
        # We need to find that address
        print("Attempting to extract flag...")
except Exception as e:
    print(f"Error during exploration: {e}")
